'use strict';

const assert = require('node:assert/strict');
const createReadingShelf = require('./solution');

assert.equal(typeof createReadingShelf, 'function');
assert.equal(createReadingShelf.name, 'createReadingShelf');

const initial = [
  { id: 5, title: 'Five', pages: 500, status: 'planned', ignored: true },
  { id: 2, title: 'Two', pages: 200, status: 'reading' }
];
const shelf = createReadingShelf(initial);
assert.deepEqual(Object.keys(shelf).sort(), ['add', 'get', 'list', 'remove', 'update']);
assert.deepEqual(shelf.list(), [
  { id: 2, title: 'Two', pages: 200, status: 'reading' },
  { id: 5, title: 'Five', pages: 500, status: 'planned' }
]);

initial[0].title = 'mutated';
initial.push({ id: 9, title: 'External', pages: 9, status: 'finished' });
assert.equal(shelf.get(5).title, 'Five');
assert.equal(shelf.get(9), null);

const listed1 = shelf.list();
const listed2 = shelf.list();
assert.notStrictEqual(listed1, listed2);
assert.notStrictEqual(listed1[0], listed2[0]);
listed1[0].title = 'changed';
listed1.pop();
assert.equal(shelf.get(2).title, 'Two');
assert.equal(shelf.list().length, 2);

const addedData = { title: 'Six', pages: 600, status: 'finished' };
const added = shelf.add(addedData);
assert.deepEqual(added, { id: 6, title: 'Six', pages: 600, status: 'finished' });
addedData.title = 'external change';
added.title = 'returned change';
assert.equal(shelf.get(6).title, 'Six');

const emptyUpdate = shelf.update(6, {});
assert.deepEqual(emptyUpdate, { id: 6, title: 'Six', pages: 600, status: 'finished' });
assert.notStrictEqual(emptyUpdate, shelf.get(6));
const patch = { title: 'Six revised', pages: 601 };
const updated = shelf.update(6, patch);
assert.deepEqual(updated, { id: 6, title: 'Six revised', pages: 601, status: 'finished' });
patch.title = 'external';
updated.status = 'planned';
assert.deepEqual(shelf.get(6), { id: 6, title: 'Six revised', pages: 601, status: 'finished' });
assert.equal(shelf.update(4, { status: 'planned' }), null);

assert.equal(shelf.remove(6), true);
assert.equal(shelf.remove(6), false);
const next = shelf.add({ title: 'Seven', pages: 700, status: 'planned' });
assert.equal(next.id, 7);

for (const value of [null, {}, 'books']) {
  assert.throws(() => createReadingShelf(value), TypeError);
}
for (const book of [
  null,
  [],
  { id: '1', title: 'T', pages: 1, status: 'planned' },
  { id: 1, title: '', pages: 1, status: 'planned' },
  { id: 1, title: 'T', pages: 0, status: 'planned' },
  { id: 1, title: 'T', pages: 1.5, status: 'planned' },
  { id: 1, title: 'T', pages: 1, status: 'other' }
]) {
  assert.throws(() => createReadingShelf([book]), TypeError);
}
for (const id of [0, -1, Number.MAX_SAFE_INTEGER + 1]) {
  assert.throws(() => createReadingShelf([{ id, title: 'T', pages: 1, status: 'planned' }]), RangeError);
}
assert.throws(() => createReadingShelf([
  { id: 1, title: 'A', pages: 1, status: 'planned' },
  { id: 1, title: 'B', pages: 2, status: 'reading' }
]), RangeError);

for (const id of [null, 1.5, '1']) {
  assert.throws(() => shelf.get(id), TypeError);
  assert.throws(() => shelf.remove(id), TypeError);
}
for (const id of [0, -1, Number.MAX_SAFE_INTEGER + 1]) {
  assert.throws(() => shelf.get(id), RangeError);
}

const beforeInvalid = shelf.list();
assert.throws(() => shelf.add({ title: '', pages: 1, status: 'planned' }), TypeError);
assert.deepEqual(shelf.list(), beforeInvalid);
assert.throws(() => shelf.update(2, { title: 'Valid', pages: 0 }), TypeError);
assert.throws(() => shelf.update(2, { status: 'planned', unexpected: true }), TypeError);
assert.throws(() => shelf.update(2, null), TypeError);
assert.deepEqual(shelf.list(), beforeInvalid);

const exhausted = createReadingShelf([{ id: Number.MAX_SAFE_INTEGER, title: 'Last', pages: 1, status: 'planned' }]);
assert.throws(() => exhausted.add({ title: 'Impossible', pages: 1, status: 'planned' }), RangeError);
assert.deepEqual(exhausted.list(), [{ id: Number.MAX_SAFE_INTEGER, title: 'Last', pages: 1, status: 'planned' }]);

